mapper.select:
SELECT v.id, v.wave_code, v.warehouse_id, v.pick_mode, v.logistics_company_id, v.storage_condition, v.order_count, v.sku_count, v.total_count, v.status, v.emp_id, v.create_time, v.create_by, w.name AS warehouse_name, lc.company_name AS logistics_company_name FROM wms_wave_order v LEFT JOIN wms_warehouse w ON w.id = v.warehouse_id LEFT JOIN wms_logistics_company lc ON lc.id = v.logistics_company_id WHERE v.is_del = 1
AND v.wave_code LIKE CONCAT('%', #{q.waveCode}, '%')
AND v.warehouse_id = #{q.warehouseId}
AND v.pick_mode = #{q.pickMode}
AND v.logistics_company_id = #{q.logisticsCompanyId}
AND v.storage_condition = #{q.storageCondition}
AND v.status = #{q.status}
ORDER BY v.id DESC
